package benchmark.integration;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class UserRepository {
    private final Connection connection;

    public UserRepository(Connection connection) {
        this.connection = connection;
    }

    public void initialize() throws SQLException {
        connection.createStatement().executeUpdate(
                "create table if not exists users(id bigint generated by default as identity, email varchar(255))");
    }

    public void save(String email) throws SQLException {
        try (PreparedStatement statement = connection.prepareStatement("insert into users(email) values (?)")) {
            statement.setString(1, email);
            statement.executeUpdate();
        }
    }

    public int countByDomain(String domain) throws SQLException {
        try (PreparedStatement statement = connection.prepareStatement(
                "select count(*) from users where email like ?")) {
            statement.setString(1, "%@" + domain);
            try (ResultSet result = statement.executeQuery()) {
                result.next();
                return result.getInt(1);
            }
        }
    }
}
